/* global Office, Excel, Word, console */

const GEMINI_MODEL = "gemini-3.5-flash-lite";
let HOST_APP = "";
const MAX_RETRY = 3;

Office.onReady((info) => {
    if (info.host === Office.HostType.Excel) {
        HOST_APP = "Excel";
    } else if (info.host === Office.HostType.Word) {
        HOST_APP = "Word";
        const p = document.getElementById("prompt_input");
        if (p) p.placeholder = "VD: Viết đoạn văn giới thiệu công ty\nVD: Sửa lỗi chính tả đoạn đang chọn\nVD: Dịch đoạn chọn sang tiếng Anh\nVD: Tóm tắt văn bản đang chọn";
    }
    document.getElementById("run_button").onclick = executeCommand;
    document.getElementById("clear_button").onclick = clearAll;
    const k = localStorage.getItem("gemini_api_key");
    if (k) document.getElementById("api_key_input").value = k;
    const ms = document.getElementById("model_select");
    if (ms) {
        const savedModel = localStorage.getItem("gemini_model");
        if (savedModel) ms.value = savedModel;
    }
});

function getModel() {
    const ms = document.getElementById("model_select");
    return ms ? ms.value : GEMINI_MODEL;
}

function setStatus(msg, type) {
    const el = document.getElementById("status_area");
    el.className = "status " + type;
    el.innerText = msg;
}

// ====== GỌI GEMINI ======
async function callGemini(apiKey, prompt) {
    const model = getModel();
    const response = await fetch(
        `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`,
        {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
                contents: [{ parts: [{ text: prompt }] }],
                generationConfig: { temperature: 0.05, maxOutputTokens: 8192, topP: 0.9 }
            })
        }
    );
    const data = await response.json();
    if (!response.ok) throw new Error(data.error?.message || "Lỗi API");
    if (!data.candidates?.length) throw new Error("Không có phản hồi.");
    return data.candidates[0].content.parts.map(p => p.text).join(" ").trim();
}

// ====== LÀM SẠCH CODE ======
function cleanCode(code) {
    code = code.replace(/```javascript/gi, "").replace(/```js/gi, "").replace(/```/g, "").trim();
    code = code.replace(/^[\s\S]*?await\s+(Excel|Word)\.run\s*\(\s*async\s*\([^)]*\)\s*=>\s*\{/i, "");
    code = code.replace(/await\s+context\.sync\(\)\s*;?\s*\}\s*\)\s*;?\s*$/i, "");
    code = code.split("\n").filter(line => {
        const t = line.trim();
        return !(t.startsWith("//") && (t.includes("Giải thích") || t.includes("Đây là code")));
    }).join("\n");
    return code.trim();
}

function colToLetter(n) {
    let s = "";
    n = n + 1;
    while (n > 0) {
        const m = (n - 1) % 26;
        s = String.fromCharCode(65 + m) + s;
        n = Math.floor((n - 1) / 26);
    }
    return s;
}

// ====== BỐI CẢNH EXCEL ======
async function getExcelContext() {
    let info = "";
    await Excel.run(async (ctx) => {
        const sel = ctx.workbook.getSelectedRange();
        sel.load("address, rowCount, columnCount, values, columnIndex, rowIndex");
        const sheet = ctx.workbook.worksheets.getActiveWorksheet();
        sheet.load("name");
        await ctx.sync();

        const isMultiCell = sel.rowCount > 1 || sel.columnCount > 1;
        const selAddr = sel.address.split("!").pop();

        info += `- Sheet: "${sheet.name}"\n`;

        if (isMultiCell) {
            info += `\n### ⚠️⚠️⚠️ NGƯỜI DÙNG ĐANG BÔI ĐEN VÙNG: ${selAddr}\n`;
            info += `### DỮ LIỆU VÙNG BÔI ĐEN ĐÃ ĐƯỢC ĐỌC SẴN VÀO BIẾN "selData".\n`;
            info += `### BẮT BUỘC dùng biến selData để đọc dữ liệu. TUYỆT ĐỐI KHÔNG dùng sheet.getUsedRange(), KHÔNG getSelectedRange().\n`;
            info += `- Kích thước vùng bôi đen: ${sel.rowCount} dòng × ${sel.columnCount} cột\n`;
            info += `- Ánh xạ cột trong vùng (index → chữ cái cột thật trên sheet):\n`;
            for (let j = 0; j < sel.columnCount; j++) {
                info += `    selData[i][${j}] = cột ${colToLetter(sel.columnIndex + j)} trên sheet\n`;
            }
            const preview = sel.values.slice(0, 25).map((r, i) => `  selData[${i}] = [${r.join(" | ")}]`).join("\n");
            info += `- Nội dung vùng bôi đen (index 0 thường là dòng tiêu đề):\n${preview}\n`;
            if (sel.rowCount > 25) info += `  ...(còn ${sel.rowCount - 25} dòng, tổng ${sel.rowCount} dòng trong selData)\n`;
        } else {
            info += `- Người dùng chọn 1 ô: ${selAddr} (CHƯA bôi đen vùng nào)\n`;
            info += `- Biến selData chỉ chứa 1 ô. Nếu cần xử lý toàn dữ liệu, dùng sheet.getUsedRange().\n`;
            const used = sheet.getUsedRangeOrNullObject();
            used.load("address, values, rowCount, columnCount");
            await ctx.sync();
            if (!used.isNullObject) {
                info += `- Toàn bộ vùng có dữ liệu: ${used.address} (${used.rowCount} dòng × ${used.columnCount} cột)\n`;
                const preview = used.values.slice(0, 20).map((r, i) => `  dòng ${i}: [${r.join(" | ")}]`).join("\n");
                info += `- Dữ liệu:\n${preview}\n`;
                if (used.rowCount > 20) info += `  ...(còn ${used.rowCount - 20} dòng nữa)\n`;
            }
        }
    });
    return info;
}

// ====== CHẠY CODE EXCEL (ĐỌC SẴN selData, selInfo) ======
async function runExcelCode(code) {
    await Excel.run(async (context) => {
        const sheet = context.workbook.worksheets.getActiveWorksheet();
        const workbook = context.workbook;

        // ĐỌC SẴN vùng bôi đen -> selData, selInfo. AI buộc phải dùng biến này.
        const sel = workbook.getSelectedRange();
        sel.load("values, rowCount, columnCount, address, columnIndex, rowIndex");
        await context.sync();

        const selData = sel.values;
        const selInfo = {
            address: sel.address,
            rowCount: sel.rowCount,
            colCount: sel.columnCount,
            startCol: sel.columnIndex,
            startRow: sel.rowIndex
        };

        const runner = new Function(
            "context", "sheet", "workbook", "Excel", "selData", "selInfo",
            `return (async () => { ${code}\nawait context.sync(); })();`
        );
        await runner(context, sheet, workbook, Excel, selData, selInfo);
        await context.sync();
    });
}

// ====== BỐI CẢNH WORD ======
async function getWordContext() {
    let info = "";
    await Word.run(async (ctx) => {
        const sel = ctx.document.getSelection();
        sel.load("text");
        await ctx.sync();
        info += `- Văn bản ĐANG CHỌN (bôi đen): "${sel.text || "(chưa chọn gì)"}"\n`;
        info += `- Độ dài đoạn chọn: ${sel.text ? sel.text.length : 0} ký tự\n`;
    });
    return info;
}

async function runWordCode(code) {
    await Word.run(async (context) => {
        const doc = context.document;
        const selection = context.document.getSelection();
        const body = context.document.body;
        const runner = new Function("context", "doc", "selection", "body", "Word",
            `return (async () => { ${code}\nawait context.sync(); })();`);
        await runner(context, doc, selection, body, Word);
        await context.sync();
    });
}

// ====== SYSTEM PROMPT EXCEL ======
const EXCEL_RULES = `Bạn là chuyên gia lập trình Office.js cho Excel, viết code CỰC KỲ chính xác.

## ĐỊNH DẠNG TRẢ VỀ (BẮT BUỘC):
- CHỈ trả về code JavaScript thuần. KHÔNG markdown, KHÔNG backtick, KHÔNG giải thích.
- Code chạy trong hàm bọc sẵn: await Excel.run(async (context) => { <CODE> await context.sync(); });
- TUYỆT ĐỐI KHÔNG tự viết "Excel.run(...)" và "context.sync()" cuối.
- Biến CÓ SẴN: context, sheet, workbook, Excel, selData, selInfo.

## ⚠️ QUY TẮC SỐ 0 - QUAN TRỌNG NHẤT (VỀ VÙNG BÔI ĐEN):
- Nếu bối cảnh ghi "NGƯỜI DÙNG ĐANG BÔI ĐEN VÙNG" → BẮT BUỘC dùng biến "selData" đã đọc sẵn để đọc dữ liệu.
- selData là mảng 2 chiều chứa CHỈ dữ liệu trong vùng bôi đen. selData[i][j] = ô dòng i, cột j (tính từ 0) TRONG VÙNG.
- selData[0] thường là dòng tiêu đề. Dữ liệu thực từ selData[1] trở đi.
- TUYỆT ĐỐI KHÔNG dùng sheet.getUsedRange() khi đã có vùng bôi đen. KHÔNG dùng workbook.getSelectedRange() để đọc lại (đã có selData).
- Nếu muốn biết cột index j ứng với cột chữ cái nào trên sheet, xem "Ánh xạ cột" trong bối cảnh.
- Chỉ khi người dùng CHƯA bôi đen (chọn 1 ô) mới được dùng sheet.getUsedRange().

## THÔNG TIN selInfo:
- selInfo.rowCount, selInfo.colCount: kích thước vùng bôi đen.
- selInfo.startCol (0=A), selInfo.startRow (0=dòng 1): vị trí bắt đầu vùng bôi đen trên sheet.

## API GHI DỮ LIỆU:
- Ô/vùng: sheet.getRange("D3") hoặc sheet.getRange("A1:C10")
- GHI giá trị: range.values = [[1],[2]]; (mảng 2 chiều ĐỦ kích thước)
- GHI công thức: range.formulas = [["=SUM(A1:A10)"]];
- Ghi mảng động n dòng m cột: sheet.getRange("P33").getResizedRange(n-1, m-1).values = mang;
- Font: range.format.font.name/.size/.bold/.italic/.color
- Nền: range.format.fill.color; Căn: range.format.horizontalAlignment="Center"
- Viền: range.format.borders.getItem("EdgeBottom").style="Continuous"
- Định dạng số: range.numberFormat phải là MẢNG ĐỦ SỐ DÒNG/CỘT.

## VÍ DỤ MẪU:

# "Cộng D1 và D2 điền vào D3"
sheet.getRange("D3").formulas = [["=D1+D2"]];

# "Tính tổng cột 3 trong vùng bôi đen, điền vào ô P33" (DÙNG selData)
let s = 0;
for (let i = 1; i < selData.length; i++) {
  const v = selData[i][3];
  s += (typeof v === "number" ? v : (parseFloat(v) || 0));
}
sheet.getRange("P33").values = [[s]];

# "Lọc giá trị không trùng cột 0 vùng bôi đen sang cột F" (DÙNG selData)
const arr = [];
for (let i = 1; i < selData.length; i++) {
  const v = selData[i][0];
  if (v !== "" && v !== null && v !== undefined) arr.push(v);
}
const unique = [...new Set(arr)];
const out = unique.map(v => [v]);
if (out.length > 0) sheet.getRange("F1").getResizedRange(out.length - 1, 0).values = out;

# "Tô đỏ ô > 100 trong vùng bôi đen" (dùng workbook.getSelectedRange để format vì cần đối tượng range)
const selR = workbook.getSelectedRange();
selR.load("values, rowCount, columnCount");
await context.sync();
for (let i = 0; i < selR.rowCount; i++)
  for (let j = 0; j < selR.columnCount; j++)
    if (typeof selR.values[i][j] === "number" && selR.values[i][j] > 100)
      selR.getCell(i, j).format.fill.color = "#FF0000";

# "Đổi font vùng bôi đen thành Times New Roman cỡ 13 in đậm"
const selR = workbook.getSelectedRange();
selR.format.font.name = "Times New Roman";
selR.format.font.size = 13;
selR.format.font.bold = true;

# "PIVOT: Gộp nhóm vùng bôi đen theo cột 0, cột 1, cột 2; tính tổng cột 3; điền kết quả từ ô P33" (DÙNG selData)
const map = {};
const order = [];
for (let i = 1; i < selData.length; i++) {
  const g0 = selData[i][0], g1 = selData[i][1], g2 = selData[i][2];
  const raw = selData[i][3];
  if ((g0 === "" || g0 === null) && (g1 === "" || g1 === null)) continue;
  const val = typeof raw === "number" ? raw : (parseFloat(raw) || 0);
  const key = String(g0) + "|||" + String(g1) + "|||" + String(g2);
  if (map[key] === undefined) { map[key] = { g0, g1, g2, sum: 0 }; order.push(key); }
  map[key].sum += val;
}
const result = order.map(k => [map[k].g0, map[k].g1, map[k].g2, map[k].sum]);
if (result.length > 0) sheet.getRange("P33").getResizedRange(result.length - 1, 3).values = result;

# "Đếm số lần xuất hiện mỗi giá trị cột 0 vùng bôi đen, ghi ra cột H, I" (DÙNG selData)
const count = {};
const ord = [];
for (let i = 1; i < selData.length; i++) {
  const v = selData[i][0];
  if (v === "" || v === null) continue;
  const k2 = String(v);
  if (count[k2] === undefined) { count[k2] = 0; ord.push(k2); }
  count[k2]++;
}
const rowsOut = ord.map(k => [k, count[k]]);
if (rowsOut.length > 0) sheet.getRange("H1").getResizedRange(rowsOut.length - 1, 1).values = rowsOut;

# "Rà soát TẤT CẢ cột tiêu đề 'Ngày tháng' TOÀN SHEET, chuyển text sang ngày thực dd/mm/yyyy" (khi CHƯA bôi đen vùng)
const used = sheet.getUsedRange();
used.load("values, rowCount, columnCount, columnIndex, rowIndex");
await context.sync();
const header = used.values[0];
const baseCol = used.columnIndex;
const baseRow = used.rowIndex;
const dateCols = [];
for (let j = 0; j < header.length; j++) {
  if (String(header[j]).trim().toLowerCase().includes("ngày tháng")) dateCols.push(j);
}
for (const col of dateCols) {
  const nRows = used.rowCount - 1;
  if (nRows < 1) continue;
  const newVals = [];
  const fmt = [];
  for (let i = 1; i < used.rowCount; i++) {
    const cv = used.values[i][col];
    const raw = String(cv).trim();
    const m = raw.match(/^(\\d{1,2})[\\/\\-.](\\d{1,2})[\\/\\-.](\\d{4})$/);
    if (typeof cv === "string" && m) {
      const d = new Date(parseInt(m[3]), parseInt(m[2]) - 1, parseInt(m[1]));
      const excelDate = Math.floor((d - new Date(1899, 11, 30)) / 86400000);
      newVals.push([excelDate]);
    } else {
      newVals.push([cv]);
    }
    fmt.push(["dd/mm/yyyy"]);
  }
  const target = sheet.getRangeByIndexes(baseRow + 1, baseCol + col, nRows, 1);
  target.values = newVals;
  target.numberFormat = fmt;
}

## QUY TẮC VÀNG:
1. Nếu ĐÃ BÔI ĐEN VÙNG → dùng selData để đọc. KHÔNG getUsedRange, KHÔNG getSelectedRange đọc lại.
2. Muốn ĐỊNH DẠNG (font/màu/viền) vùng bôi đen → dùng workbook.getSelectedRange() (vì cần đối tượng range để format), nhưng ĐỌC dữ liệu vẫn dùng selData.
3. selData[0] là dòng tiêu đề, dữ liệu bắt đầu selData[1].
4. Phép tính đơn giản trên vùng liền kề → có thể dùng CÔNG THỨC =SUM.
5. numberFormat PHẢI là mảng 2 chiều ĐỦ số dòng và cột. KHÔNG dùng [["fmt"]] cho nhiều dòng.
6. Định dạng ngày dùng "dd/mm/yyyy". Ngày là TEXT phải PARSE thành số ngày Excel rồi ghi values + numberFormat.
7. Số ngày Excel = Math.floor((new Date(y,m-1,d) - new Date(1899,11,30)) / 86400000).
8. "Rà soát TOÀN BỘ / tất cả cột" → QUÉT HẾT, KHÔNG dùng break.
9. Ghi mảng động dùng getResizedRange(n-1, m-1) đúng kích thước.
10. Số dạng text ("123") dùng parseFloat() để tính.
11. Bỏ qua dòng rỗng khi nhóm/lọc/đếm.`;

// ====== SYSTEM PROMPT WORD ======
const WORD_RULES = `Bạn là chuyên gia Office.js cho Microsoft Word.

## ĐỊNH DẠNG TRẢ VỀ:
- CHỈ trả về code JavaScript thuần. KHÔNG markdown, KHÔNG backtick, KHÔNG giải thích.
- Code chạy trong: await Word.run(async (context) => { <CODE> await context.sync(); });
- Biến có sẵn: context, doc, selection, body, Word.

## API:
- Đọc đoạn chọn: selection.load("text"); await context.sync(); rồi selection.text
- Thay đoạn chọn: selection.insertText("nội dung", Word.InsertLocation.replace);
- Chèn cuối tài liệu: body.insertParagraph("nội dung", Word.InsertLocation.end);
- Chèn sau đoạn chọn: selection.insertText("...", Word.InsertLocation.after);
- Font: selection.font.name/.size/.bold/.italic/.color
- Căn giữa: selection.paragraphs.getFirst().alignment = Word.Alignment.centered;

## VÍ DỤ:

# "Viết đoạn văn giới thiệu công ty xây dựng ABC"
body.insertParagraph("Công ty Xây dựng ABC là đơn vị hàng đầu trong lĩnh vực thi công công trình dân dụng và công nghiệp...", Word.InsertLocation.end);

# "Sửa/viết lại đoạn đang chọn cho hay hơn"
selection.insertText("nội dung đã viết lại hoàn chỉnh", Word.InsertLocation.replace);

# "Dịch đoạn chọn sang tiếng Anh"
selection.insertText("bản dịch tiếng Anh hoàn chỉnh", Word.InsertLocation.replace);

## QUY TẮC VÀNG:
- Yêu cầu VIẾT/SỬA/DỊCH/TÓM TẮT → TỰ tạo nội dung HOÀN CHỈNH, KHÔNG để placeholder.
- Nội dung tự nhiên, chuyên nghiệp, đúng ngữ pháp.`;

// ====== HÀM CHÍNH ======
async function executeCommand() {
    const apiKey = document.getElementById("api_key_input").value.trim();
    const userPrompt = document.getElementById("prompt_input").value.trim();
    const btn = document.getElementById("run_button");

    if (!apiKey) { setStatus("⚠️ Nhập API key.", "error"); return; }
    if (!userPrompt) { setStatus("⚠️ Nhập yêu cầu.", "error"); return; }

    localStorage.setItem("gemini_api_key", apiKey);
    const ms = document.getElementById("model_select");
    if (ms) localStorage.setItem("gemini_model", ms.value);
    btn.disabled = true;

    try {
        let contextInfo, rules, runFunc;
        if (HOST_APP === "Excel") {
            contextInfo = await getExcelContext();
            rules = EXCEL_RULES;
            runFunc = runExcelCode;
        } else {
            contextInfo = await getWordContext();
            rules = WORD_RULES;
            runFunc = runWordCode;
        }

        let lastError = "";
        let code = "";

        for (let attempt = 1; attempt <= MAX_RETRY; attempt++) {
            setStatus(attempt === 1 ? "🧠 Đang phân tích..." : `🔄 Đang thử lại (lần ${attempt}/${MAX_RETRY})...`, "loading");

            let prompt;
            if (attempt === 1) {
                prompt = `${rules}\n\n## BỐI CẢNH HIỆN TẠI:\n${contextInfo}\n\n## YÊU CẦU NGƯỜI DÙNG:\n${userPrompt}\n\nHãy viết code chính xác (nhớ dùng selData nếu người dùng đã bôi đen vùng):`;
            } else {
                prompt = `${rules}\n\n## BỐI CẢNH:\n${contextInfo}\n\n## YÊU CẦU:\n${userPrompt}\n\n## CODE TRƯỚC BỊ LỖI:\n${code}\n\n## THÔNG BÁO LỖI:\n${lastError}\n\nPhân tích lỗi và viết lại code ĐÚNG. Chỉ trả về code:`;
            }

            code = cleanCode(await callGemini(apiKey, prompt));
            console.log(`=== Lần ${attempt} - Code (${HOST_APP}) ===\n${code}\n===================`);

            try {
                setStatus("⚙️ Đang thực thi...", "loading");
                await runFunc(code);
                setStatus(attempt === 1 ? "✅ Thành công!" : `✅ Thành công (sau ${attempt} lần thử)!`, "success");
                btn.disabled = false;
                return;
            } catch (execError) {
                lastError = execError.message;
                console.warn(`Lần ${attempt} lỗi:`, lastError);
                if (attempt === MAX_RETRY) {
                    throw new Error(`Đã thử ${MAX_RETRY} lần vẫn lỗi. Lỗi cuối: ${lastError}`);
                }
            }
        }
    } catch (error) {
        console.error(error);
        setStatus("❌ " + error.message, "error");
    } finally {
        btn.disabled = false;
    }
}

function clearAll() {
    document.getElementById("prompt_input").value = "";
    document.getElementById("status_area").className = "status";
    document.getElementById("status_area").innerText = "";
}